UPDATE fee
SET
    closing_settlement = #{status}
WHERE
    settlement_month = #{settlementMonth}
    AND ent_ceo_no = #{entCeoNo}  
    AND closing_settlement = '1.마감(정산)전';

UPDATE fee SET provision_date = #{currentDate}, closing_settlement = '2.마감(정산)완료' WHERE fee_no IN
#{feeNo}
AND closing_settlement = '2.마감(정산)완료';

UPDATE monthly_fee
SET
    pay_status = '지급'
WHERE
    settlement_month = #{settlementMonth}
    AND ent_ceo_no = #{entCeoNo}
    AND (pay_status IS NULL OR pay_status != '지급');
